			knuckle(fork, trunkR * .95);
			for (let i = 1; i < lobes.length; i++) {
				const L = lobes[i];
				if (L.r < .3) continue;
				const dir = new Vector3(L.c.x - fork.x, 0, L.c.z - fork.z);
				const reach = dir.length();
				dir.normalize();
				const m1 = fork.clone().addScaledVector(dir, reach * .4).setY(fork.y + .1 + rng() * .08);
				const m2 = fork.clone().addScaledVector(dir, reach * .75).setY(fork.y + .04 + rng() * .18);
				const end = new Vector3(L.c.x * 1.02, L.c.y - L.r * .5, L.c.z * 1.02);
				limb(fork, m1, .11, .08, lod === 0 ? 7 : 4);
				knuckle(m1, .085);
				limb(m1, m2, .08, .055, lod === 0 ? 6 : 4);
				knuckle(m2, .058);
				if (lod === 0) limb(m2, end, .055, .025, 4);
			}
