				const s0 = from.clone().lerp(to, .5 + j * .25);
				const out = new Vector3(to.x - from.x, 0, to.z - from.z).normalize();
				const side = new Vector3(-out.z, 0, out.x).multiplyScalar(j ? -1 : 1);
