	foliage.setAttribute("position", new Float32BufferAttribute(posArr, 3));
	foliage.setAttribute("normal", new Float32BufferAttribute(nrmArr, 3));
	foliage.setAttribute("color", new Float32BufferAttribute(colArr, 3));
	foliage.setAttribute("aLeaf", new Float32BufferAttribute(new Array(posArr.length / 3).fill(1), 1));
