		const lim2 = [];
		for (let li = 0; li < L; li++) {
			const d = li === L - 1 ? Infinity : this._levels[li].maxDist * this._lodScale;
			lim2.push(d * d);
		}
		const counts = new Array(L).fill(0);
		const mArr = this.meshes.map((m) => m.instanceMatrix.array);
		const cArr = this.meshes.map((m) => m.instanceColor ? m.instanceColor.array : null);
