				plains: [1, 0],
				mountain: [1, .3],
				sound: [0, 1],
				coast: [-1, 0],
				city: [1, 0],
				appalachia: [1, 0],
				desert: [1, 0],
				north_woods: [1, 0],
				upper_midwest: [1, 0],
				ozarks: [1, 0],
				hill_country: [1, 0],
				rust_belt: [1, 0]
