			bayou: WATER_LOOKS.bayou,
			sound: WATER_LOOKS.sound,
			mountain: WATER_LOOKS.campus,
			coast: WATER_LOOKS.campus,
			city: WATER_LOOKS.campus,
			appalachia: WATER_LOOKS.river,
			desert: WATER_LOOKS.campus,
			north_woods: WATER_LOOKS.pond,
			upper_midwest: WATER_LOOKS.pond,
