//#region src/game/region/neighbors.ts
function mulberry32(seed) {
	let a = seed >>> 0;
	return () => {
		a = a + 1831565813 >>> 0;
		let t = a;
		t = Math.imul(t ^ t >>> 15, t | 1);
		t ^= t + Math.imul(t ^ t >>> 7, t | 61);
		return ((t ^ t >>> 14) >>> 0) / 4294967296;
	};
}
function planNeighbors(t, count = 3) {
	const rnd = mulberry32(t.seed * 31 + 5);
	const out = [];
	const c = 67 / 2;
	const wy = t.region.waterY ?? -Infinity;
	for (let tries = 0; tries < 400 && out.length < count; tries++) {
		const a = (rnd() - .5) * Math.PI * 1.4;
		const d = 70 + rnd() * 150;
		const x = c + Math.cos(a) * d, z = c + Math.sin(a) * d;
		if (Math.max(Math.abs(x - c), Math.abs(z - c)) < c + 22) continue;
		if (out.some((f) => Math.hypot(f.x - x, f.z - z) < 60)) continue;
		let lo = Infinity, hi = -Infinity;
		for (const [dx, dz] of [
			[-9, -9],
			[9, -9],
			[-9, 9],
			[9, 9],
			[0, 0]
		]) {
			const h = t.height(x + dx, z + dz);
			lo = Math.min(lo, h);
			hi = Math.max(hi, h);
		}
		if (hi - lo > 1.2 || lo < wy + .6) continue;
		if (Math.abs(z - t.creek.zAt(x)) < 16) continue;
		const rot = Math.floor(rnd() * 4) * Math.PI / 2 + (rnd() - .5) * .1;
		out.push({
			x,
			z,
			rot,
			big: rnd() < .35
		});
	}
	return out;
}
