		hair: keep?.hair ?? (rnd() < .05 ? 10130832 : pick(HAIR_COLORS)),
		pack: keep?.pack ?? pick(PACK_COLORS),
		hasPack,
		longHair: keep?.longHair ?? rnd() < .4,
		shoe: opt.jogger ? .9 : rnd(),
		coat,
		shorts,
		hat
