/** Outfit for a persona (see Persona). Skin / hair stay with `keep` when given. */
function pickPersonaWear(rnd, persona, opt, keep) {
	const pick = (a) => a[Math.floor(rnd() * a.length) % a.length];
	if (persona === "student") return pickWear(rnd, opt, keep);
	const fanOk = persona === "kid" || persona === "resident" || persona === "parent";
	const base = pickWear(rnd, {
		...opt,
		team: fanOk ? opt.team : null,
		teamShare: (opt.teamShare ?? .5) * .8
	}, keep);
	const inColors = !!opt.team && (base.shirt === opt.team.primary || base.shirt === opt.team.secondary);
	base.hasPack = false;
	switch (persona) {
		case "graduate":
		case "faculty":
			base.shirt = persona === "faculty" ? opt.color ?? 1911900 : rnd() < .06 ? 2503242 : 1316120;
			base.pants = 1973792;
			base.coat = 3;
			base.shorts = false;
			base.hat = -2;
			base.shoe = rnd() * .5;
			break;
		case "parent":
			if (!inColors) base.shirt = pick(DRESS_SHIRTS);
			base.pants = pick(DRESS_PANTS);
			base.shorts = opt.season === "summer" && rnd() < .2;
			if (opt.season !== "summer" && rnd() < .35) base.coat = Math.max(base.coat, 1);
			if (base.hat >= 0 && rnd() < .6) base.hat = -1;
			if (!keep && rnd() < .3) base.hair = pick(GRAY_HAIR);
			break;
		case "elder":
			base.shirt = pick([...DRESS_SHIRTS, ...TWEED]);
			base.pants = pick(DRESS_PANTS);
			base.shorts = false;
			base.coat = opt.season === "summer" ? 0 : rnd() < .5 ? 2 : 1;
			if (!keep) base.hair = pick(GRAY_HAIR);
			base.longHair = base.longHair && rnd() < .4;
			base.shoe = rnd() * .5;
			break;
		case "kid":
			if (!inColors) base.shirt = pick(KID_SHIRTS);
			base.hasPack = rnd() < .15;
			break;
		case "resident":
			if (!keep && rnd() < .3) base.hair = pick(GRAY_HAIR);
			if (opt.season !== "summer" && base.coat === 0 && rnd() < .4) base.coat = 1;
			base.hasPack = rnd() < .1;
			break;
		case "lecturer":
			base.shirt = pick(TWEED);
			base.pants = pick(DRESS_PANTS);
			base.coat = 1;
			base.shorts = false;
			base.hat = -1;
			base.hasPack = rnd() < .3;
			if (!keep && rnd() < .45) base.hair = pick(GRAY_HAIR);
			break;
		case "volunteer":
			base.shirt = opt.color ?? 2919034;
			base.coat = 0;
			base.pants = pick([
				3885670,
				2634311,
				7308968,
				6119526
			]);
			base.shorts = opt.season === "summer" && rnd() < .5;
			base.hat = -1;
			break;
		case "vendor":
			base.shirt = pick(APRONS);
			base.pants = pick([
				3885670,
				5067320,
				6119526
			]);
			base.coat = 1;
			base.shorts = false;
			if (!keep && rnd() < .3) base.hair = pick(GRAY_HAIR);
			break;
	}
	return base;
}
