	hair.scale(.95, 1.2, 1.03);
	hair.rotateX(-.35);
	hair.translate(0, SHOULDER_Y + .072, -.004);
	add(hair, P_HAIR);
	add(box(.066, .075, .018, 0, SHOULDER_Y + .03, -.034), P_LONGHAIR);
	add(box(.086, .12, .044, 0, SHOULDER_Y - .075, -.054), P_PACK);
