	const top = new Vector3(.035, .665, .055);
	const shaftDir = top.clone().sub(hand);
	const shaft = new CylinderGeometry(.006, .006, shaftDir.length() + .05, 4);
	shaft.applyQuaternion(new Quaternion().setFromUnitVectors(new Vector3(0, 1, 0), shaftDir.clone().normalize()));
	shaft.translate((hand.x + top.x) / 2, (hand.y + top.y) / 2, (hand.z + top.z) / 2);
	add(shaft, P_UMB_SHAFT);
	const canopy = new ConeGeometry(.17, .075, 8, 1, false);
	canopy.translate(top.x, top.y - .03, top.z);
	add(canopy, P_UMB_CANOPY);
	const board = new BoxGeometry(.1, .008, .1);
	board.rotateY(.2);
	board.translate(0, SHOULDER_Y + .118, -.004);
	add(board, P_BOARD);
	add(box(.12, .085, .09, 0, SHOULDER_Y - .13, .105), P_BOX);
