	add(box(.012, .035, .055, hx, HAND_Y - .215, -.012), P_AXE, 2, true);
	add(rod(.007, .5, hx, HAND_Y + .05, HAND_Y - .45), P_HOE, 2);
	add(box(.06, .035, .008, hx, HAND_Y - .45, .012), P_HOE, 2, true);
	const rifle = new BoxGeometry(.016, .42, .024);
	rifle.rotateZ(.95);
