	const batteryKwh = working.reduce((a, st) => a + (UTILITY[st.kind]?.batteryKwh ?? 0), 0) * (1 - u.batteryFade);
	const genKw = working.reduce((a, st) => a + (UTILITY[st.kind]?.genKw ?? 0), 0);
	const p = plant$1(s);
